async function expectPermanentRedirects(expected: Record<string, string>): Promise<Redirect[]> {
  const all = await getRedirects();
  const bySource = new Map(all.map((r) => [r.source, r]));
  for (const [source, destination] of Object.entries(expected)) {
    const r = bySource.get(source);
    expect(r, `a redirect exists for ${source}`).toBeTruthy();
    expect(r!.destination).toBe(destination);
    expect(r!.permanent).toBe(true);
  }
  return all;
}

function sizeLabel(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  const k = bytes / 1024;
  return k < 1024 ? `${Math.round(k)} KB` : `${(k / 1024).toFixed(1)} MB`;
}

export default function AdminLayout({ children }: { children: ReactNode }) {
  // The per-request CSP nonce minted by middleware (apps/web/middleware.ts, UNC-CSP). The inline
  // window.__ENV script below is APP-emitted (not one of Next's own scripts, which Next nonces
  // automatically), so under the prod `script-src 'nonce-…'` policy it must carry the nonce itself
  // or the browser blocks it. Undefined in any route without the CSP (only /admin sets it today).
  const nonce = headers().get("x-nonce") ?? undefined;
  // Emitted ONLY when set — the default per-host build bakes NEXT_PUBLIC_API_URL (DEPLOY-006) and
  // needs no injection, so this is inert and byte-identical for existing deployments. The accessor
  // in apps/web/lib/adminApi.ts (`apiBase`) reads window.__ENV.API_URL first, else the baked value.
  const runtimeApiUrl = process.env.API_PUBLIC_URL;
  const envScript = runtimeApiUrl
    ? `window.__ENV={API_URL:${scriptSafeJson(runtimeApiUrl)}};`
    : null;
  return (
    <>
      {envScript ? (
        <script nonce={nonce} dangerouslySetInnerHTML={{ __html: envScript }} />
      ) : null}
      <AdminProviders>{children}</AdminProviders>
    </>
  );
}

export function AccessTabs() {
  const pathname = usePathname();
  const me = useQuery({ queryKey: ["me"], queryFn: fetchMe });
  if (!me.data) return null;
  const sections = visibleAccessSections(me.data);
  if (sections.length === 0) return null;
  return (
    <nav className="flex gap-1 overflow-x-auto" aria-label="Access sections">
      {sections.map((s) => {
        const active = pathname === s.href || pathname.startsWith(`${s.href}/`);
        return (
          <Link
            key={s.key}
            href={s.href}
            aria-current={active ? "page" : undefined}
            className={cx(
              "flex min-h-[44px] items-center whitespace-nowrap border-b-2 px-3 text-sm font-semibold transition",
              active
                ? "border-[var(--accent)] text-[var(--accent)]"
                : "border-transparent text-[var(--ink-muted)] hover:text-[var(--ink)]",
              FOCUS_RING,
            )}
          >
            {s.label}
          </Link>
        );
      })}
    </nav>
  );
}

