export async function POST(req: Request): Promise<Response> {
  try {
    const body = (await req.json()) as Record<string, unknown>;
    // Both the legacy `{"csp-report": {...}}` and the Reporting-API `[{body:{...}}]` shapes.
    const report =
      (Array.isArray(body) ? (body[0] as Record<string, unknown>)?.body : body["csp-report"]) ??
      body;
    const r = (report ?? {}) as Record<string, unknown>;
    const directive = r["violated-directive"] ?? r["effectiveDirective"] ?? "?";
    const blocked = r["blocked-uri"] ?? r["blockedURL"] ?? "?";
    // eslint-disable-next-line no-console -- intentional ops signal for a silently-blocked tag
    console.warn(`[csp-report] directive=${String(directive)} blocked=${String(blocked)}`);
  } catch {
    // malformed / empty report — ignore, never surface.
  }
  return new Response(null, { status: 204 });
}

export function ThirdPartyTags({ vendors }: { vendors: Vendors }): React.JSX.Element | null {
  const [consent, setConsent] = useState<ConsentState | null>(null);

  useEffect(() => {
    const read = () => {
      const w = window as unknown as ConsentWindow;
      setConsent(w.__incmsConsent ?? null);
    };
    read(); // pick up a decision ConsentBoot already hydrated before hydration
    window.addEventListener(CONSENT_EVENT, read as EventListener);
    return () => window.removeEventListener(CONSENT_EVENT, read as EventListener);
  }, []);

  const analyticsOk = isGranted(consent, "analytics");
  const adsOk = isGranted(consent, "ads");

  const gtm = vendors.gtm_id?.trim() ?? "";
  const ga4 = vendors.ga4_id?.trim() ?? "";
  const pixel = vendors.pixel_id?.trim() ?? "";

  const showGtm = analyticsOk && isValidVendorId("gtm", gtm);
  const showGa4 = analyticsOk && isValidVendorId("ga4", ga4);
  const showPixel = adsOk && isValidVendorId("pixel", pixel);

  if (!showGtm && !showGa4 && !showPixel) return null;

  return (
    <>
      {showGtm ? (
        <Script id="incms-gtm" strategy="afterInteractive">
          {`(function(w,d,s,l,i){w[l]=w[l]||[];w[l].push({'gtm.start':new Date().getTime(),event:'gtm.js'});var f=d.getElementsByTagName(s)[0],j=d.createElement(s),dl=l!='dataLayer'?'&l='+l:'';j.async=true;j.src='https://www.googletagmanager.com/gtm.js?id='+i+dl;f.parentNode.insertBefore(j,f);})(window,document,'script','dataLayer','${gtm}');`}
        </Script>
      ) : null}

      {showGa4 ? (
        <>
          <Script
            id="incms-ga4-src"
            strategy="afterInteractive"
            src={`https://www.googletagmanager.com/gtag/js?id=${ga4}`}
          />
          <Script id="incms-ga4-init" strategy="afterInteractive">
            {`window.dataLayer=window.dataLayer||[];window.gtag=window.gtag||function(){window.dataLayer.push(arguments);};gtag('js',new Date());gtag('config','${ga4}');`}
          </Script>
        </>
      ) : null}

      {showPixel ? (
        <Script id="incms-meta-pixel" strategy="lazyOnload">
          {`!function(f,b,e,v,n,t,s){if(f.fbq)return;n=f.fbq=function(){n.callMethod?n.callMethod.apply(n,arguments):n.queue.push(arguments)};if(!f._fbq)f._fbq=n;n.push=n;n.loaded=!0;n.version='2.0';n.queue=[];t=b.createElement(e);t.async=!0;t.src=v;s=b.getElementsByTagName(e)[0];s.parentNode.insertBefore(t,s)}(window,document,'script','https://connect.facebook.net/en_US/fbevents.js');fbq('consent','grant');fbq('init','${pixel}');fbq('track','PageView');`}
        </Script>
      ) : null}
    </>
  );
}

export function RatingInput({
  value,
  max = 5,
  onChange,
}: {
  value: unknown;
  max?: number;
  onChange: (rating: number | undefined) => void;
}) {
  const current = typeof value === "number" ? value : 0;
  const stars = Math.max(1, Math.min(10, Math.round(max)));

  return (
    <div className="mt-1 flex items-center gap-2">
      <div className="flex items-center gap-0.5">
        {Array.from({ length: stars }, (_, i) => i + 1).map((n) => (
          <button
            key={n}
            type="button"
            aria-label={`${n} star${n === 1 ? "" : "s"}`}
            onClick={() => onChange(n === current ? undefined : n)}
            className="p-1.5"
          >
            <Star
              className={cx(
                "h-5 w-5 transition",
                n <= current
                  ? "fill-[var(--b2)] text-[var(--b2)]"
                  : "fill-transparent text-[var(--ink-faint)] hover:text-[var(--b2)]",
              )}
            />
          </button>
        ))}
      </div>
      <input
        type="number"
        min={0}
        max={stars}
        step={0.1}
        value={typeof value === "number" ? value : ""}
        onChange={(e) => onChange(e.target.value === "" ? undefined : Number(e.target.value))}
        className={cx(ADMIN_FIELD, "w-20 px-2 py-1")}
        aria-label="Rating value"
      />
      <span className="text-xs text-[var(--ink-faint)]">/ {stars}</span>
    </div>
  );
}

