describe("FilterSelect — the list filter control (clone fold)", () => {
  // ONE render helper for all three arms. Three near-identical renderToStaticMarkup calls are
  // themselves a clone, and the ratchet said so the moment they first landed — the fold's own
  // lesson applied to the fold's own tests.
  const html = (className?: string) =>
    renderToStaticMarkup(
      <FilterSelect
        label="Filter by status"
        value=""
        options={[{ value: "", label: "All" }]}
        onChange={() => {}}
        className={className}
      />,
    );

  it("turns `label` into the accessible name — a filter has no visible caption", () => {
    expect(html()).toContain('aria-label="Filter by status"');
  });

  it("carries the 44px touch floor", () => {
    // A CLASS-PRESENCE check, and it says so: the node env has no layout engine, so the COMPUTED
    // height is browser-verified. This catches the class being dropped, not a Tailwind no-op.
    expect(html()).toContain("min-h-[44px]");
  });

  it("appends a caller className without displacing the recipe", () => {
    expect(html("w-40")).toContain("w-40");
    expect(html("w-40")).toContain("min-h-[44px]");
  });

  it("calls onChange BEFORE resetting the page, and tolerates no `paging`", () => {
    // ORDER matters: a reset firing first would be overwritten by a caller that also sets an offset
    // in its own onChange. Driven through the returned element's props — the node env dispatches
    // no events.
    const seen: string[] = [];
    const el = FilterSelect({
      label: "Filter by status",
      value: "",
      options: [{ value: "", label: "All" }],
      onChange: (v) => seen.push(`change:${v}`),
      paging: { setOffset: (o) => seen.push(`offset:${o}`) },
    });
    (el.props.onChange as (e: { target: { value: string } }) => void)({
      target: { value: "x" },
    });
    expect(seen).toEqual(["change:x", "offset:0"]);

    const bare = FilterSelect({
      label: "Filter by status",
      value: "",
      options: [{ value: "", label: "All" }],
      onChange: () => {},
    });
    expect(() =>
      (bare.props.onChange as (e: { target: { value: string } }) => void)({
        target: { value: "y" },
      }),
    ).not.toThrow();
  });
});

function fetchCalls(): FetchCall[] {
  const out: FetchCall[] = [];
  for (const rel of tree.scanned) {
    const src = sourceOf(rel);
    const raw = rawOf(rel);
    const rawStarts = rawCallStarts(raw);
    const starts = callStarts(src);
    const mappable = rawStarts.length === starts.length;
    starts.forEach((start, n) => {
      const open = start + src.slice(start).indexOf("(");
      const close = matchDelim(src, open, "(", ")");
      if (close < 0) return;
      const line = mappable ? lineAt(raw, rawStarts[n] ?? start) : lineAt(src, start);
      out.push({
        file: rel,
        at: `${rel}:${mappable ? "" : "~"}${line}`,
        args: src.slice(open + 1, close),
      });
    });
  }
  return out;
}

async function fixtureState(): Promise<Fixture> {
  if (probed) return probed;
  const missing = (what: string): Fixture => ({
    ok: false,
    why: `paywall fixture absent: ${what}. This is a SKIP, never a silent pass — the cases in this file ran nothing. Arrange it with:\n  ${SEED_COMMAND}`,
  });

  if (!existsSync(RUN_ARTIFACT)) {
    probed = missing("apps/web/e2e/editor/.paywall-run.json was never written");
    return probed;
  }
  let run: Run;
  try {
    run = JSON.parse(readFileSync(RUN_ARTIFACT, "utf8")) as Run;
  } catch (err) {
    probed = missing(`apps/web/e2e/editor/.paywall-run.json is unreadable (${String(err)})`);
    return probed;
  }
  if (!run.pagePath || !run.entitledEmail) {
    probed = missing("apps/web/e2e/editor/.paywall-run.json names no item page or no member");
    return probed;
  }

  const page = await fetch(`${API_URL}/public/pages?path=${encodeURIComponent(run.pagePath)}`);
  if (!page.ok) {
    probed = missing(`the item page ${run.pagePath} is not published on ${API_URL}`);
    return probed;
  }
  const signIn = await fetch(`${API_URL}/account/auth/login`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ email: run.entitledEmail, password: fixture.password }),
  });
  if (!signIn.ok) {
    probed = missing(
      `the entitled member ${run.entitledEmail} cannot sign in on ${API_URL} (${signIn.status})`,
    );
    return probed;
  }
  probed = { ok: true, run };
  return probed;
}

export function adminSearchHref(item: AdminSearchItem): string {
  switch (item.kind) {
    case "admin":
      // A local index hit carries its own resolved deep link (screen/section/setting), built by
      // adminIndex from the derivation sources — never a user-supplied URL.
      return item.href ?? "#";
    case "page":
      return `/admin/pages/${item.id}/edit`;
    case "entry":
      return item.type_key ? `/admin/collections/${item.type_key}` : "/admin/collections";
    case "media":
      return `/admin/media?q=${encodeURIComponent(item.title)}`;
    case "published":
      return item.path ?? "#";
  }
}

