export function useUrlQueryState(key: string): [string, (next: string) => void] {
  const [value, setValue] = useState("");

  // Mount-only deep-link seed (client-only; avoids a useSearchParams Suspense boundary).
  useEffect(() => {
    if (typeof window === "undefined") return;
    const initial = new URLSearchParams(window.location.search).get(key);
    if (initial) setValue(initial);
    // Mount-only: an initial read, not a live URL->state sync.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const set = useCallback(
    (next: string) => {
      setValue(next);
      if (typeof window === "undefined") return;
      const params = new URLSearchParams(window.location.search);
      if (next.trim()) params.set(key, next.trim());
      else params.delete(key);
      const qs = params.toString();
      const url = window.location.pathname + (qs ? `?${qs}` : "") + window.location.hash;
      window.history.replaceState(null, "", url);
    },
    [key],
  );

  return [value, set];
}

export function formatPercent(
  value: number,
  unit: string,
  decimal = ".",
): string {
  if (!Number.isFinite(value) || Math.abs(value) >= MAX_FORMATTABLE) return "";
  let text = value.toFixed(2);
  if (text.includes(".")) text = text.replace(/\.?0+$/, "");
  return `${text.replace(".", decimal)}${unit}`;
}

export function intentUrl(network: string, url: string, title: string): string {
  const u = encodeURIComponent(url);
  const t = encodeURIComponent(title);
  switch (network) {
    case "x":
      return `https://x.com/intent/tweet?url=${u}${title ? `&text=${t}` : ""}`;
    case "facebook":
      return `https://www.facebook.com/sharer/sharer.php?u=${u}`;
    case "linkedin":
      return `https://www.linkedin.com/sharing/share-offsite/?url=${u}`;
    case "email":
      return `mailto:?subject=${t}&body=${u}`;
    default:
      return "#";
  }
}

function runTsc(): { status: number; output: string } {
  const tscEntry = createRequire(join(PKG_ROOT, "package.json")).resolve("typescript/bin/tsc");
  try {
    const stdout = execFileSync(
      process.execPath,
      [tscEntry, "-p", HARNESS_TSCONFIG, "--noEmit", "--pretty", "false"],
      { cwd: PKG_ROOT, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] },
    );
    return { status: 0, output: stdout };
  } catch (err) {
    const e = err as { status?: number; stdout?: string; stderr?: string };
    return { status: e.status ?? 1, output: `${e.stdout ?? ""}${e.stderr ?? ""}` };
  }
}

function walk(fields: readonly ComputeField[]): Walk {
  const byName = new Map<string, ComputeField>();
  for (const f of fields) {
    if (f && typeof f.name === "string") byName.set(f.name, f);
  }

  const state = new Map<string, 1 | 2>(); // 1 = on the stack, 2 = emitted
  const stack: string[] = [];
  const order: string[] = [];
  let error: string | null = null;

  const visit = (name: string): void => {
    const field = byName.get(name);
    if (!field?.compute) return; // a plain input field — a leaf, nothing to order
    if (state.get(name) === 2) return;
    if (state.get(name) === 1) {
      const at = stack.indexOf(name);
      error = `compute cycle: ${[...stack.slice(at), name].join(" → ")}`;
      return;
    }

    state.set(name, 1);
    stack.push(name);
    const from = Array.isArray(field.compute.from) ? field.compute.from : [];
    for (const dep of from) {
      if (typeof dep !== "string" || !byName.has(dep)) {
        error = `compute field "${name}" reads "${String(dep)}", which no field in this form declares`;
        break;
      }
      visit(dep);
      if (error) break;
    }
    stack.pop();
    state.set(name, 2);
    if (!error) order.push(name);
  };

  for (const f of fields) {
    if (!f?.compute) continue;
    visit(f.name);
    if (error) break;
  }
  return { order: error ? [] : order, error };
}

