export const Callout = Node.create({
  name: "callout",
  group: "block",
  content: "block+",
  defining: true,

  addAttributes() {
    return {
      tone: {
        default: "info" as CalloutTone,
        parseHTML: (el) => toneFromClass((el as HTMLElement).getAttribute("class") ?? ""),
        // The tone is carried by the class in renderHTML — never emit a `tone` attribute
        // (nh3 would strip it anyway).
        renderHTML: () => ({}),
      },
    };
  },

  parseHTML() {
    return [{ tag: "div.nc-callout" }];
  },

  renderHTML({ node }) {
    const tone = TONES.includes(node.attrs.tone) ? node.attrs.tone : "info";
    return ["div", { class: `nc-callout nc-callout-${tone}` }, 0];
  },
});

function theirs(name: string, className?: string): string {
