export async function fetchFormTicket(ref: string): Promise<string | undefined> {
  try {
    const res = await fetch(
      `${apiBase()}/public/forms/${encodeURIComponent(ref)}/ticket`,
      { cache: "no-store" },
    );
    if (!res.ok) return undefined;
    const json = (await res.json()) as { submit_ticket?: unknown };
    return typeof json.submit_ticket === "string" ? json.submit_ticket : undefined;
  } catch {
    return undefined;
  }
}

export function validateCustomPalette(tokens: Partial<PaletteTokens>): string[] {
  const problems: string[] = [];
  for (const key of PALETTE_TOKEN_KEYS) {
    const v = tokens[key];
    if (typeof v !== "string" || !isHexColor(v)) problems.push(`"${key}" must be a hex color`);
  }
  if (problems.length) return problems;
  if (luminance(tokens.bg!) < 0.6) problems.push("Background must be light (the admin chrome needs it).");
  if (luminance(tokens.ink!) > 0.25) problems.push("Primary text must be dark.");
  if (contrast("#FFFFFF", tokens.hero!) < 4.5)
    problems.push("Dark-section color (hero) must be dark enough for white text (AA 4.5:1).");
  return problems;
}

