function eagerConfig(data: Data): Config {
  const components: Record<string, unknown> = {};
  for (const type of collectDocTypes(data)) {
    const mod = MODULES[type];
    if (!mod) continue; // unknown type omitted, same as the walker
    const render = resolveRender(mod, type);
    if (!render) continue;
    const Wrapped = withAppearance(withHtmlOverride(render)) as unknown as (
      p: Record<string, unknown>,
    ) => ReactNode;
    const slotNames = SLOT_FIELD_NAMES[type];
    const fields = slotNames
      ? Object.fromEntries(slotNames.map((n) => [n, { type: "slot" }]))
      : undefined;
    components[type] = {
      ...(fields ? { fields } : {}),
      render: (props: Record<string, unknown>) => <Wrapped {...props} />,
    };
  }
  return {
    components,
    root: { render: ({ children }: { children?: ReactNode }) => <>{children}</> },
  } as unknown as Config;
}

