function Loader() {
  const params = useParams<{ menuId: string }>();
  const menuId = params.menuId;
  const me = useQuery({ queryKey: ["me"], queryFn: fetchMe });
  const canManage = (me.data?.permissions ?? []).includes("menu.manage");
  const menu = useQuery({
    queryKey: ["menus", menuId],
    queryFn: () => getMenu(menuId),
  });

  // Error must exit the loading state, not spin forever (the DES-d066 dropped-error branch): on a
  // failed INITIAL menu fetch `isLoading` is false but `menu.data` is undefined, so the old
  // `!menu.data` guard returned <Spinner/> permanently. The `&& !menu.data` keeps a populated editor
  // mounted when a BACKGROUND refetch fails (e.g. the post-save invalidation), so unsaved edits
  // aren't discarded and the user isn't bounced to a full-page error after a successful save.
  if (menu.isError && !menu.data) return <ErrorState retry={() => void menu.refetch()} />;
  if (menu.isLoading || !menu.data) return <Spinner />;
  return <MenuEditor initial={menu.data} canManage={canManage} />;
}

