function applyConsent(analytics: ConsentValue, ads: ConsentValue): void {
  const w = window as unknown as ForcedWindow;
  const state = { v: CONSENT_VERSION, analytics, ads, ts: Date.now() };
  const secure = location.protocol === "https:" ? ";secure" : "";
  document.cookie =
    `${CONSENT_COOKIE}=${encodeURIComponent(JSON.stringify(state))}` +
    `;path=/;max-age=${60 * 60 * 24 * 365};samesite=lax${secure}`;
  w.__incmsConsent = state;
  // Mirror into Consent Mode v2 (ConsentBoot already installed window.gtag + dataLayer).
  w.dataLayer = w.dataLayer || [];
  const gtag =
    w.gtag ||
    ((...a: unknown[]) => {
      (w.dataLayer as unknown[]).push(a);
    });
  const update: Record<string, ConsentValue> = {};
  for (const [cat, signals] of Object.entries(CONSENT_SIGNALS)) {
    const v = cat === "analytics" ? analytics : ads;
    for (const sig of signals) update[sig] = v;
  }
  gtag("consent", "update", update);
  // Withdrawal teardown (DES-d082 review fix): the `incms:consent` event makes the facade unmount the
  // Pixel `<Script>` node, but that does NOT unload an already-executed `fbevents.js`, and the gtag
  // update only degrades GOOGLE — so on an ads DENY actively revoke Meta's Pixel + clear its cookies
  // (else "Reject all" keeps tracking). No-op when the Pixel was never loaded.
  if (ads === "denied") revokeAdsClientTracking(w);
  window.dispatchEvent(new CustomEvent(CONSENT_EVENT, { detail: state }));
}

function Grouped({ type, children }: { type: string; children: ReactNode }) {
  const all = Children.toArray(children);
  const byName = new Map<string, ReactNode[]>();
  const unkeyed: ReactNode[] = [];
  for (const child of all) {
    const name = fieldNameFromChildKey(
      isValidElement(child) ? (child.key as string | null) : null,
    );
    if (!name) {
      unkeyed.push(child);
      continue;
    }
    const list = byName.get(name);
    if (list) list.push(child);
    else byName.set(name, [child]);
  }
  // Slot lookup from the static config map (premise recorded in R-9: live slot set ⊆ static).
  // basePuckType: a plugin block's virtual alias isn't in the static map — resolve to the
  // registered base so slot lookup + the PluginBlock grouping rules apply (BLOCK-aGraftedBough-1 S4).
  const baseType = basePuckType(type);
  const fields =
    (config.components as Record<string, { fields?: Record<string, { type?: string }> }>)[baseType]
      ?.fields ?? {};
  const { leading, sections, other } = partitionFieldKeys(baseType, [...byName.keys()], {
    isSlot: (n) => fields[n]?.type === "slot",
  });
  const pick = (keys: string[]) => keys.flatMap((k) => byName.get(k) ?? []);
  const otherChildren = [...pick(other), ...unkeyed];
  return (
    <>
      {pick(leading)}
      {sections.map((s) => (
        // Keyed per block TYPE so a type switch remounts and re-reads stored/default state (R-3).
        // A lone non-empty section always opens (R-4) — stored state applies only to multi-section
        // blocks; writes fire from FieldSection's guarded onToggled (user toggles only) — M2.
        <FieldSection
          key={`${type}:${s.id}`}
          title={s.label}
          open={
            sections.length === 1
              ? defaultOpenFor(s.id, 1) // R-4 lone-section rule beats stored state
              : readGroupOpen(safeLocalStorage(), type, s.id, defaultOpenFor(s.id, sections.length))
          }
          onToggled={(open) => writeGroupOpen(safeLocalStorage(), type, s.id, open)}
        >
          {pick(s.keys)}
        </FieldSection>
      ))}
      {otherChildren.length > 0 ? (
        <FieldSection key={`${type}:other`} title="Other" open>
          {otherChildren}
        </FieldSection>
      ) : null}
    </>
  );
}

