export function useHashHighlight(): void {
  useEffect(() => {
    let timer: ReturnType<typeof setTimeout> | undefined;
    let raf = 0;
    // Retry across frames: after a cross-page deep-link the target section may mount a data-load
    // later, so keep looking for it for up to ~0.5s before giving up.
    const go = (attempt = 0) => {
      const id = decodeURIComponent(window.location.hash.slice(1));
      if (!id) return;
      const el = document.getElementById(id);
      if (!el) {
        if (attempt < 30) raf = requestAnimationFrame(() => go(attempt + 1));
        return;
      }
      el.scrollIntoView({ behavior: "smooth", block: "start" });
      el.classList.add("nc-hash-flash");
      if (timer) clearTimeout(timer);
      timer = setTimeout(() => el.classList.remove("nc-hash-flash"), 1600);
    };
    const onHashChange = () => go(0);
    raf = requestAnimationFrame(() => go(0));
    window.addEventListener("hashchange", onHashChange);
    return () => {
      cancelAnimationFrame(raf);
      window.removeEventListener("hashchange", onHashChange);
      if (timer) clearTimeout(timer);
    };
  }, []);
}

