export function resolveBands(p: Partial<MenuPresentation> | null | undefined): ResolvedBands {
  const pres = p ?? {};
  // BLOCK-bTrimmedVestibule-1: `sticky` is TRI-state. FOLD to the boolean every downstream consumer
  // already expects — `"trigger"` pins the drawer TRIGGER and leaves the bar unpinned, so for BOTH
  // bands it resolves exactly like `false`. Without this the value is wrong in two DIFFERENT ways at
  // once: `"trigger"` is truthy in TS, and the Python mirror does `bool(raw_sticky)` (menu_bands.py),
  // True for any non-empty string — while `SiteChrome` asks `=== true` and would say false. A
  // truthiness consumer and a strict-equality consumer disagreeing across the language boundary is
  // exactly the coercion-drift class this module's docstring exists to prevent.
  const sticky = (pres.sticky ?? true) === true;
  const transparent = !!pres.transparentUntilScroll;
  const autoHide = !!pres.autoHide;
  const stickUtility = pres.stickUtility ?? true;
  const dbl = pres.layout === "double-row";
  const legacy = pres.utility == null;
  const legacySplit = legacy && dbl && stickUtility === false;

  const bar: ResolvedBand = {
    sticky,
    transparent,
    autoHide: autoHide && !legacySplit && sticky,
  };

  let strip: ResolvedBand;
  if (legacy) {
    // Reproduce today: strip pins only when the bar is sticky AND stickUtility isn't false; it inherits
    // the bar's transparency; auto-hide carries the whole-shell split-utility
    // suppression AND is gated on the strip being PINNED (BLOCK-bUnpinnedSash-1).
    const stripSticky = sticky && stickUtility !== false;
    const stripTransparent = transparent;
    strip = {
      sticky: stripSticky,
      transparent: stripTransparent,
      autoHide: autoHide && !legacySplit && stripSticky,
    };
  } else {
    // Per-band model: an unset sub-field inherits the bar's value; auto-hide is gated to a PINNED
    // band (never on a static or overlay strip — prevents a 422 on a materialized-but-static utility).
    const u = pres.utility ?? {};
    const stripSticky = u.sticky ?? sticky;
    const stripTransparent = u.transparentUntilScroll ?? transparent;
    strip = {
      sticky: stripSticky,
      transparent: stripTransparent,
      autoHide: (u.autoHide ?? false) && stripSticky,
    };
  }

  return { bar, strip };
}

function heroVideoSources(webm?: ImageRef, mp4?: ImageRef): VideoSource[] {
  const out: VideoSource[] = [];
  const seen = new Set<string>();
  for (const ref of [webm, mp4]) {
    const url = safeImgSrc(normalizeImageRef(ref).url);
    const type = url ? videoSourceType(url) : null;
    if (url && type && !seen.has(url)) {
      seen.add(url);
      out.push({ src: url, type });
    }
  }
  out.sort(
    (a, b) =>
      (a.type === "video/webm" ? 0 : 1) - (b.type === "video/webm" ? 0 : 1),
  );
  return out;
}

