function withoutOrphans(
  env: GcReportEnvelope | undefined,
  removed: { type: string; id: string }[],
): GcReportEnvelope | undefined {
  if (!env?.report) return env;
  const gone = new Set(removed.map((r) => `${r.type}:${r.id}`));
  const orphans = env.report.orphans.filter((o) => !gone.has(`${o.type}:${o.id}`));
  const byType: Record<string, number> = {};
  for (const o of orphans) byType[o.type] = (byType[o.type] ?? 0) + 1;
  return {
    ...env,
    report: {
      ...env.report,
      orphans,
      counts: { ...env.report.counts, orphans: orphans.length, orphans_by_type: byType },
    },
  };
}

