function prepareBody(
  html: string,
  injectIds: boolean,
  depth: TocDepth,
): { html: string; toc: TocEntry[] } {
  const toc: TocEntry[] = [];
  const used = new Set<string>();
  const out = html.replace(
    /<(h[234])\b([^>]*)>([\s\S]*?)<\/\1>/gi,
    (_m, tag: string, attrs: string, inner: string) => {
      const level = Number(tag.slice(1));
      const text = inner
        .replace(/<[^>]+>/g, "")
        .replace(/\s+/g, " ")
        .trim();
      let id = attrs.match(/\sid="([^"]*)"/i)?.[1];
      let nextAttrs = attrs;
      if (id) {
        // Dedup EXISTING ids too: a consolidated or hand-authored body can repeat a heading id,
        // which would collide on the DOM id, the #anchor target, and the ToC React key.
        if (used.has(id)) {
          const baseId = id;
          let cand = baseId;
          let n = 2;
          while (used.has(cand)) cand = `${baseId}-${n++}`;
          const finalId = cand;
          nextAttrs = attrs.replace(
            /(\sid=")[^"]*(")/i,
            (_m, a: string, b: string) => a + finalId + b,
          );
          id = finalId;
        }
      } else if (injectIds) {
        const base = slugify(text);
        let cand = base;
        let n = 2;
        while (used.has(cand)) cand = `${base}-${n++}`;
        id = cand;
        nextAttrs = `${attrs} id="${id}"`;
      }
      if (id) used.add(id);
      const include = level === 2 || (depth === "h2h3" && level === 3);
      if (id && include && text) toc.push({ level, id, text });
      return `<${tag}${nextAttrs}>${inner}</${tag}>`;
    },
  );
  return { html: out, toc };
}

describe("registry <-> manifest parity (promotes the ARCH-117 dev guard to a hard gate)", () => {
  const registryTypes = new Set(ALL_BLOCKS.map((b) => b.type));
  const manifestTypes = new Set(BLOCK_MANIFEST.map((m) => m.type));

  it("every registered block is in the manifest (else the API 422s its saves)", () => {
    const missing = [...registryTypes].filter((t) => !manifestTypes.has(t));
    expect(missing).toEqual([]);
  });

  it("every manifest type has a registered block (else the API accepts unrenderable docs)", () => {
    const unrenderable = [...manifestTypes].filter((t) => !registryTypes.has(t));
    expect(unrenderable).toEqual([]);
  });

  // WU-D U4 (AC14) — the two checks above compare SETS, so a duplicate type is invisible to them:
  // `registry.tsx` appends `...LOCAL_BLOCKS` LAST and `:502` builds the Puck config with
  // Object.fromEntries (last wins), so a compiled block silently shadowing a core one passes both.
  // The generator refuses that collision at build time; these two make the invariant a gate here too.
  const duplicates = (types: string[]) =>
    [...new Set(types.filter((t, i) => types.indexOf(t) !== i))].sort();

  it("no block type is registered twice (a Set comparison cannot see this)", () => {
    expect(ALL_BLOCKS.length).toBe(registryTypes.size);
    expect(duplicates(ALL_BLOCKS.map((b) => b.type))).toEqual([]);
  });

  it("no manifest type is listed twice", () => {
    expect(BLOCK_MANIFEST.length).toBe(manifestTypes.size);
    expect(duplicates(BLOCK_MANIFEST.map((m) => m.type))).toEqual([]);
  });

  it("manifest category matches the live BlockDef category (closes the dead-category drift)", () => {
    const byType = new Map(ALL_BLOCKS.map((b) => [b.type, b.category]));
    const mismatches = BLOCK_MANIFEST.filter((m) => byType.get(m.type) !== m.category).map(
      (m) => `${m.type}: manifest=${m.category} registry=${String(byType.get(m.type))}`,
    );
    expect(mismatches).toEqual([]);
  });
});

