export function plainTextToHtml(
  text: string,
  opts: { preserveLineBreaks?: boolean; singleParagraph?: boolean } = {},
): HtmlString {
  // The input is escaped before any markup is added, so the output is safe HTML by
  // construction — a legitimate HtmlString minter (BLOCK-015).
  if (opts.singleParagraph) {
    const collapsed = escapeHtml(text ?? "").replace(/\s+/g, " ").trim();
    return asSanitizedHtml(collapsed ? `<p>${collapsed}</p>` : "");
  }
  const paragraphs = (text ?? "")
    .split(/\n\s*\n/)
    .map((p) => p.trim())
    .filter(Boolean);
  return asSanitizedHtml(
    paragraphs
      .map((p) => {
        const escaped = escapeHtml(p);
        const inner = opts.preserveLineBreaks
          ? escaped.replace(/\n/g, "<br>")
          : escaped.replace(/\s*\n\s*/g, " ");
        return `<p>${inner}</p>`;
      })
      .join(""),
  );
}

function useLocations(p: GeoMapProps): Loc[] {
  const entry = useEntry();
  return useMemo(() => {
    if (p.source === "collection") {
      return (p.resolvedPins ?? [])
        .slice(0, 100)
        .map((pin, i) => ({ ...pin, id: pin.id || `g${i}` }))
        .filter((pin) => Number.isFinite(pin.lat) && Number.isFinite(pin.lng));
    }
    // `currentEntry` is a PinMap-only mode; GeoMap reads authored static pins or a resolved collection.
    void entry;
    return (p.pinsStatic ?? [])
      .map((s, i): Loc | null => {
        const lat = num(s.lat);
        const lng = num(s.lng);
        if (lat === null || lng === null || !(s.label ?? "").trim()) return null;
        return { id: `s${i}`, lat, lng, label: String(s.label), href: s.href };
      })
      .filter((x): x is Loc => x !== null)
      .slice(0, 100);
  }, [p, entry]);
}

function closure(entry: string): Set<string> {
  const seen = new Set<string>([entry]);
  const queue = [entry];
  while (queue.length) {
    const file = queue.shift() as string;
    let src: string;
    try {
      src = readFileSync(file, "utf8");
    } catch {
      continue;
    }
    const specs = [
      ...src.matchAll(/(?:from\s+|import\s*\(\s*)["']([^"']+)["']/g),
    ].map((m) => m[1]);
    for (const spec of specs) {
      if (typeof spec !== "string") continue;
      const next = resolveLocal(file, spec);
      if (next && !seen.has(next)) {
        seen.add(next);
        queue.push(next);
      }
    }
  }
  return seen;
}

