export function isSafeSegment(value: string): boolean {
  if (typeof value !== "string" || value.length === 0 || value.length > SEGMENT_MAX) return false;
  if (value.includes("/") || value.includes("\\")) return false;
  if (value.includes("?") || value.includes("#")) return false;
  // `%2e` is refused WHEREVER it appears rather than only as a whole `%2e%2e`, because the mixed
  // spellings (`.%2e`, `%2e.`) traverse just as well and no real place id carries an escaped dot.
  if (/%2f|%5c|%25|%2e/i.test(value)) return false;
  // Escaped, never literal — `remoteBinding.ts:95-97` records why a raw control byte in a guard
  // source made git treat that module as binary and shipped the guard with an unreviewable diff.
  if (/[\u0000-\u001f\u007f]/.test(value)) return false;
  if (value === "." || value === "..") return false;
  return true;
}

