describe("sweep completeness (ARCH-dGildedSextant-2 AC2)", () => {
  // A future block declaring a bare `heading: { type: "text" }` reds HERE rather than silently
  // shipping without the affordance. Bento is not exempted: its heading is a nested arrayField, so a
  // top-level walk never reaches it (its sharedFields are eyebrow/title/copy/tiles).
  it("every top-level heading field in the registry is the custom heading field", () => {
    // Assert `capabilityKind`, not merely `type === "custom"`: ANY custom field satisfies the latter,
    // so a heading swapped to some unrelated custom widget would pass. And walk each DESIGN's own
    // fields as well as `config.fields` — for a section the latter is `unionFields()`'s output, which
    // is last-design-wins, so a migrated final design would mask an unmigrated earlier one. Both were
    // confirmed blind spots in this gate's first revision (review-2 `headingField.test.tsx:152/155`).
    const offenders: string[] = [];
    let seen = 0;
    const check = (where: string, h: { type?: string; capabilityKind?: string } | undefined) => {
      if (!h) return;
      seen++;
      if (h.type !== "custom" || !h.capabilityKind) {
        offenders.push(`${where} (type: ${String(h.type)}, capabilityKind: ${String(h.capabilityKind)})`);
      }
    };
    type F = Record<string, { type?: string; capabilityKind?: string }> | undefined;
    for (const b of ALL_BLOCKS) {
      const cfg = b.config as { fields?: F; designs?: Record<string, { fields?: F }> };
      check(b.type, (cfg.fields ?? {}).heading);
      for (const [key, design] of Object.entries(cfg.designs ?? {})) {
        check(`${b.type}/${key}`, (design.fields ?? {}).heading);
      }
    }
    expect(seen).toBeGreaterThanOrEqual(20); // the walk actually reaches the registry
    expect(offenders).toEqual([]);
  });
});

